#include <stdio.h>

#define MAXN 100005

static int N, Q;
static long long bit[MAXN];
static int val[MAXN];

static void update(int i, long long delta) {
    for (; i <= N; i += i & (-i))
        bit[i] += delta;
}

static long long query(int i) {
    long long s = 0;
    for (; i > 0; i -= i & (-i))
        s += bit[i];
    return s;
}

int main(void) {
    if (scanf("%d %d", &N, &Q) != 2) return 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d", &val[i]);
        update(i, val[i]);
    }
    for (int q = 0; q < Q; q++) {
        int type;
        scanf("%d", &type);
        if (type == 0) {
            int k, p;
            scanf("%d %d", &k, &p);
            update(k, (long long)p - val[k]);
            val[k] = p;
        } else {
            int k;
            scanf("%d", &k);
            printf("%lld\n", query(k));
        }
    }
    return 0;
}
